// ❌ OLD: A plain {} inherits from Object.prototype, so its prototype
// chain includes keys like 'constructor', 'hasOwnProperty', '__proto__'.
// If untrusted input names collide, lookups/iterations can misbehave.
const map = {}; // ❌ OLD: prototype chain → Object.prototype → null
map['toString'] = 'injected'; // shadows the inherited toString

console.log(Object.keys(map)); // ['toString']
// Reading map.someMissingKey walks the chain up to Object.prototype.
// This is why using {} for a dictionary is fragile for arbitrary keys.

// ✅ NEW: Object.create(null) creates an object whose [[Prototype]] is
// null — no inherited Object.prototype keys. Ideal for dictionaries keyed
// by arbitrary (possibly untrusted) strings.
const map = Object.create(null); // ✅ NEW: [[Prototype]] = null, chain ends here
map['toString'] = 'injected'; // now a plain own property, nothing to collide
map['__proto__'] = 'safe'; // not interpreted as a setter — it's just a key

console.log(Object.keys(map)); // ['toString', '__proto__']
// Property lookups stop at the object itself; no prototype walk occurs.
